       clientId: 'YOUR_GITHUB_OAUTH_APP_CLIENT_ID',
       deviceCode: device_code,
       interval,
       expiresIn: expires_in,
     });

     // token 可用于后续 Octokit 请求
     const octokit = new Octokit({ auth: token });
     // … your CLI logic …
   }
